// Memory Wiki plugin module implements gateway behavior.
import { formatErrorMessage } from "openclaw/plugin-sdk/error-runtime";
import { normalizeSourceRefV2, resolveDefaultAgentId } from "openclaw/plugin-sdk/memory-host-core";
import { readPositiveIntegerParam } from "openclaw/plugin-sdk/param-readers";
import type { OpenClawConfig, OpenClawPluginApi } from "../api.js";
import { applyMemoryWikiMutation, normalizeMemoryWikiMutationInput } from "./apply.js";
import { compileMemoryWikiVault } from "./compile.js";
import {
  WIKI_SEARCH_BACKENDS,
  WIKI_SEARCH_CORPORA,
  type ResolvedMemoryWikiConfig,
} from "./config.js";
import { listMemoryWikiImportInsights } from "./import-insights.js";
import { listMemoryWikiImportRuns } from "./import-runs.js";
import { ingestMemoryWikiSource } from "./ingest.js";
import { lintMemoryWikiVault } from "./lint.js";
import { listMemoryWikiPalace } from "./memory-palace.js";
import {
  probeObsidianCli,
  runObsidianCommand,
  runObsidianDaily,
  runObsidianOpen,
  runObsidianSearch,
} from "./obsidian.js";
import { getMemoryWikiPage, searchMemoryWiki, WIKI_SEARCH_MODES } from "./query.js";
import { syncMemoryWikiImportedSources } from "./source-sync.js";
import { buildMemoryWikiDoctorReport, resolveMemoryWikiStatus } from "./status.js";
import { initializeMemoryWikiVault } from "./vault.js";
import type { MemoryWikiReadIdentity } from "./owner-read.js";
import type { MemoryWikiProjectionService } from "./retrieval-index.js";
import type { MemoryWikiEmbeddingService } from "./retrieval-embeddings.js";
import type { MemoryWikiVectorService } from "./retrieval/vector-service.js";
import type { MemoryWikiRerankService } from "./retrieval-rerank.js";
import { retrieveMemoryWiki } from "./retrieval/plan-service.js";

const READ_SCOPE = "operator.read" as const;
const WRITE_SCOPE = "operator.write" as const;
const ADMIN_SCOPE = "operator.admin" as const;
const LOCAL_FILE_INGEST_SCOPE = ADMIN_SCOPE;
type GatewayMethodContext = Parameters<
  Parameters<OpenClawPluginApi["registerGatewayMethod"]>[1]
>[0];
type GatewayRespond = GatewayMethodContext["respond"];

function readIdentity(
  request: Record<string, unknown>,
  client: GatewayMethodContext["client"],
): MemoryWikiReadIdentity | undefined {
  if (request.readIdentity === undefined) return undefined;
  if (client?.connect?.client?.mode !== "backend")
    throw new Error("Knowledge read identity is backend-owned.");
  const value = request.readIdentity;
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("Invalid knowledge read identity.");
  const facts = value as Record<string, unknown>;
  const providerRefs =
    Array.isArray(facts.egressProviderRefs) &&
    facts.egressProviderRefs.every((entry) => typeof entry === "string" && entry.trim())
      ? (facts.egressProviderRefs as string[])
      : [];
  return {
    agentSessionKey: readStringParam(facts, "agentSessionKey"),
    sessionId: readStringParam(facts, "sessionId"),
    workspaceId: readStringParam(facts, "workspaceId"),
    workspaceDir: readStringParam(facts, "workspaceDir"),
    egressProviderRefs: providerRefs,
  };
}

function readStringParam(params: Record<string, unknown>, key: string): string | undefined;
function readStringParam(
  params: Record<string, unknown>,
  key: string,
  options: { required: true },
): string;
function readStringParam(
  params: Record<string, unknown>,
  key: string,
  options?: { required?: boolean },
): string | undefined {
  const value = params[key];
  if (typeof value === "string" && value.trim()) {
    return value.trim();
  }
  if (options?.required) {
    throw new Error(`${key} is required.`);
  }
  return undefined;
}

function readEnumParam<T extends string>(
  params: Record<string, unknown>,
  key: string,
  allowed: readonly T[],
): T | undefined {
  const value = readStringParam(params, key);
  if (!value) {
    return undefined;
  }
  if ((allowed as readonly string[]).includes(value)) {
    return value as T;
  }
  throw new Error(`${key} must be one of: ${allowed.join(", ")}.`);
}

function respondError(respond: GatewayRespond, error: unknown) {
  const message = formatErrorMessage(error);
  respond(false, undefined, { code: "internal_error", message });
}

function resolveGatewayAgentId(
  requestParams: Record<string, unknown>,
  appConfig: OpenClawConfig | undefined,
): string | undefined {
  return (
    readStringParam(requestParams, "agentId") ??
    (appConfig ? resolveDefaultAgentId(appConfig) : undefined)
  );
}

async function syncImportedSourcesIfNeeded(
  config: ResolvedMemoryWikiConfig,
  appConfig?: OpenClawConfig,
) {
  await syncMemoryWikiImportedSources({ config, appConfig });
}

export function registerMemoryWikiGatewayMethods(params: {
  api: OpenClawPluginApi;
  config: ResolvedMemoryWikiConfig;
  appConfig?: OpenClawConfig;
  projection?: MemoryWikiProjectionService;
  embedding?: MemoryWikiEmbeddingService;
  vector?: MemoryWikiVectorService;
  rerank?: MemoryWikiRerankService;
}) {
  const { api, config, appConfig } = params;
  api.registerGatewayMethod(
    "wiki.retrieve",
    async ({ params: request, respond, client }) => {
      try {
        const identity = readIdentity(request, client);
        if (!identity) throw new Error("Retrieval requires a backend-owned identity");
        if (typeof request.query !== "string") throw new Error("Retrieval query must be a string");
        for (const key of ["profile", "mode"] as const) {
          if (request[key] !== undefined && (typeof request[key] !== "string" || !request[key]))
            throw new Error(`Invalid retrieval ${key}`);
        }
        const refs = Array.isArray(request.sourceRefs)
          ? request.sourceRefs.map(normalizeSourceRefV2)
          : [];
        if (
          request.sourceRefs !== undefined &&
          (!Array.isArray(request.sourceRefs) || refs.some((ref) => !ref))
        )
          throw new Error("Invalid retrieval source pins");
        if (
          request.deadlineAtMs !== undefined &&
          (typeof request.deadlineAtMs !== "number" || !Number.isFinite(request.deadlineAtMs))
        )
          throw new Error("Invalid retrieval deadline");
        const profile = readEnumParam(request, "profile", ["local", "quality", "research"] as const);
        const mode = readEnumParam(request, "mode", ["off", "manual", "suggest", "auto-read"] as const);
        respond(
          true,
          await retrieveMemoryWiki({
            config,
            appConfig,
            identity,
            query: readStringParam(request, "query") ?? "",
            profile,
            mode,
            explicitRefs: refs.filter((ref) => ref !== undefined),
            deadlineAtMs: request.deadlineAtMs as number | undefined,
            requestId: readStringParam(request, "requestId"),
            projection: params.projection,
            embedding: params.embedding,
            vector: params.vector,
            rerank: params.rerank,
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );
  if (params.vector) {
    const vector = params.vector;
    for (const operation of [
      "start",
      "stop",
      "status",
      "idle",
      "rebuild",
      "optimize",
      "search",
    ] as const) {
      api.registerGatewayMethod(
        `wiki.vector.${operation}`,
        async ({ params: request, respond, client }) => {
          try {
            const identity = readIdentity(request, client);
            if (!identity) throw new Error("Vector operations require a backend-owned identity");
            let result: unknown;
            if (operation === "start") {
              const backend = readEnumParam(request, "backend", [
                "sqlite-flat",
                "lancedb-ann",
              ] as const);
              if (!backend) throw new Error("Vector backend is required");
              await vector.enable(identity, backend);
              result = await vector.status(identity);
            } else if (operation === "search") {
              result = await vector.search(
                identity,
                readStringParam(request, "query", { required: true }),
                readPositiveIntegerParam(request, "limit"),
              );
            } else if (operation === "status") result = await vector.status(identity);
            else {
              if (operation === "stop") await vector.disable(identity);
              else await vector[operation](identity);
              result = await vector.status(identity);
            }
            respond(true, result);
          } catch (error) {
            respondError(respond, error);
          }
        },
        { scope: ["status", "search"].includes(operation) ? READ_SCOPE : WRITE_SCOPE },
      );
    }
  }
  if (params.rerank) {
    const rerank = params.rerank;
    for (const operation of ["status", "configure", "retry", "cancel", "disable"] as const) {
      api.registerGatewayMethod(
        `wiki.rerank.${operation}`,
        async ({ params: request, respond, client }) => {
          try {
            const identity = readIdentity(request, client);
            if (!identity)
              throw new Error("Rerank operations require a backend-owned read identity");
            let result: unknown;
            if (operation === "configure") {
              result = await rerank.configure(
                {
                  mode: readEnumParam(request, "mode", ["local", "remote"] as const) ?? "remote",
                  providerRef: readStringParam(request, "providerRef"),
                  model: readStringParam(request, "model"),
                  endpoint: readStringParam(request, "endpoint"),
                },
                identity,
              );
            } else if (operation === "status") result = rerank.status(identity);
            else result = await rerank[operation](identity);
            respond(true, result);
          } catch (error) {
            respondError(respond, error);
          }
        },
        { scope: operation === "status" ? READ_SCOPE : WRITE_SCOPE },
      );
    }
  }

  if (params.embedding) {
    const embedding = params.embedding;
    for (const operation of [
      "status",
      "configure",
      "retry",
      "cancel",
      "disable",
      "embed",
    ] as const) {
      api.registerGatewayMethod(
        `wiki.embedding.${operation}`,
        async ({ params: request, respond, client }) => {
          try {
            const identity = readIdentity(request, client);
            if (!identity)
              throw new Error("Embedding operations require a backend-owned read identity");
            let result: unknown;
            if (operation === "configure") {
              const mode = readEnumParam(request, "mode", ["local", "remote"] as const);
              if (!mode) throw new Error("Embedding mode is required");
              result = await embedding.configure(
                {
                  mode,
                  providerRef: readStringParam(request, "providerRef"),
                  model: readStringParam(request, "model"),
                },
                identity,
              );
            } else if (operation === "embed") {
              if (
                request.deadlineAt !== undefined &&
                (typeof request.deadlineAt !== "number" || !Number.isFinite(request.deadlineAt))
              ) {
                throw new Error("Invalid embedding deadline");
              }
              const deadlineAt =
                typeof request.deadlineAt === "number" ? request.deadlineAt : undefined;
              const kind = readEnumParam(request, "kind", ["query", "document"] as const);
              if (kind === "query") {
                result = await embedding.embed(identity, {
                  kind,
                  text: readStringParam(request, "text", { required: true }),
                  expectedSpaceId: readStringParam(request, "expectedSpaceId"),
                  deadlineAt,
                });
              } else if (kind === "document" && Array.isArray(request.sources)) {
                const sources = request.sources.map(normalizeSourceRefV2);
                if (sources.some((source) => !source))
                  throw new Error("Invalid embedding source pins");
                result = await embedding.embed(identity, {
                  kind,
                  sources: sources.filter((source) => source !== undefined),
                  expectedSpaceId: readStringParam(request, "expectedSpaceId"),
                  deadlineAt,
                });
              } else throw new Error("Embedding inputs are required");
            } else {
              result = await embedding[operation](identity);
            }
            respond(true, result);
          } catch (error) {
            respondError(respond, error);
          }
        },
        { scope: operation === "status" ? READ_SCOPE : WRITE_SCOPE },
      );
    }
  }

  if (params.projection) {
    const projection = params.projection;
    const operations = [
      "start",
      "stop",
      "status",
      "reconcile",
      "rebuild",
      "idle",
      "search",
    ] as const;
    for (const operation of operations) {
      api.registerGatewayMethod(
        `wiki.index.${operation}`,
        async ({ params: request, respond, client }) => {
          try {
            const identity = readIdentity(request, client);
            if (!identity)
              throw new Error("Projection operations require a backend-owned read identity");
            const result =
              operation === "start"
                ? await projection.enable(identity)
                : operation === "stop"
                  ? await projection.disable(identity)
                  : operation === "status"
                    ? projection.status(identity)
                    : operation === "reconcile" || operation === "rebuild"
                      ? await projection.reconcile(identity, operation === "rebuild")
                      : operation === "idle"
                        ? await projection.idle(identity)
                        : await projection.search(
                            identity,
                            readStringParam(request, "query", { required: true }),
                            readPositiveIntegerParam(request, "limit"),
                          );
            respond(true, result);
          } catch (error) {
            respondError(respond, error);
          }
        },
        { scope: ["status", "search"].includes(operation) ? READ_SCOPE : WRITE_SCOPE },
      );
    }
  }

  api.registerGatewayMethod(
    "wiki.status",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(
          true,
          await resolveMemoryWikiStatus(config, {
            appConfig,
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.importRuns",
    async ({ params: requestParams, respond }) => {
      try {
        const limit = readPositiveIntegerParam(requestParams, "limit");
        respond(true, await listMemoryWikiImportRuns(config, limit !== undefined ? { limit } : {}));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.importInsights",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(true, await listMemoryWikiImportInsights(config));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.palace",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(true, await listMemoryWikiPalace(config));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.init",
    async ({ respond }) => {
      try {
        respond(true, await initializeMemoryWikiVault(config));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.doctor",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        const status = await resolveMemoryWikiStatus(config, {
          appConfig,
        });
        respond(true, buildMemoryWikiDoctorReport(status));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.compile",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(true, await compileMemoryWikiVault(config));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.ingest",
    async ({ params: requestParams, respond }) => {
      try {
        const inputPath = readStringParam(requestParams, "inputPath", { required: true });
        const title = readStringParam(requestParams, "title");
        respond(
          true,
          await ingestMemoryWikiSource({
            config,
            inputPath,
            ...(title ? { title } : {}),
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: LOCAL_FILE_INGEST_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.lint",
    async ({ respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(true, await lintMemoryWikiVault(config));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.bridge.import",
    async ({ respond }) => {
      try {
        respond(
          true,
          await syncMemoryWikiImportedSources({
            config: { ...config, vaultMode: "bridge" },
            appConfig,
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.unsafeLocal.import",
    async ({ respond }) => {
      try {
        respond(
          true,
          await syncMemoryWikiImportedSources({
            config: { ...config, vaultMode: "unsafe-local" },
            appConfig,
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.search",
    async ({ params: requestParams, respond, client }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        const query = readStringParam(requestParams, "query", { required: true });
        const maxResults = readPositiveIntegerParam(requestParams, "maxResults");
        const searchBackend = readEnumParam(requestParams, "backend", WIKI_SEARCH_BACKENDS);
        const searchCorpus = readEnumParam(requestParams, "corpus", WIKI_SEARCH_CORPORA);
        const mode = readEnumParam(requestParams, "mode", WIKI_SEARCH_MODES);
        const agentId = resolveGatewayAgentId(requestParams, appConfig);
        respond(
          true,
          await searchMemoryWiki({
            config,
            appConfig,
            ...(agentId ? { agentId } : {}),
            query,
            maxResults,
            searchBackend,
            searchCorpus,
            mode,
            readIdentity: readIdentity(requestParams, client),
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.apply",
    async ({ params: requestParams, respond }) => {
      try {
        await syncImportedSourcesIfNeeded(config, appConfig);
        respond(
          true,
          await applyMemoryWikiMutation({
            config,
            mutation: normalizeMemoryWikiMutationInput(requestParams),
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  const wikiLifecycleMethods = [
    ["wiki.update", "update"],
    ["wiki.merge", "merge"],
    ["wiki.archive", "archive"],
    ["wiki.revoke", "revoke"],
    ["wiki.delete", "delete"],
    ["wiki.restore", "restore"],
  ] as const;
  for (const [method, op] of wikiLifecycleMethods) {
    api.registerGatewayMethod(
      method,
      async ({ params: requestParams, respond }) => {
        try {
          await syncImportedSourcesIfNeeded(config, appConfig);
          respond(
            true,
            await applyMemoryWikiMutation({
              config,
              mutation: normalizeMemoryWikiMutationInput({
                ...requestParams,
                op,
              }),
            }),
          );
        } catch (error) {
          respondError(respond, error);
        }
      },
      { scope: WRITE_SCOPE },
    );
  }

  api.registerGatewayMethod(
    "wiki.get",
    async ({ params: requestParams, respond, client }) => {
      try {
        const lookup = readStringParam(requestParams, "lookup", { required: true });
        const fromLine = readPositiveIntegerParam(requestParams, "fromLine");
        const lineCount = readPositiveIntegerParam(requestParams, "lineCount");
        const searchBackend = readEnumParam(requestParams, "backend", WIKI_SEARCH_BACKENDS);
        const searchCorpus = readEnumParam(requestParams, "corpus", WIKI_SEARCH_CORPORA);
        const agentId = resolveGatewayAgentId(requestParams, appConfig);
        const sourceRef = normalizeSourceRefV2(requestParams.sourceRef);
        if (requestParams.sourceRef !== undefined && !sourceRef)
          throw new Error("Invalid SourceRef/v2 pin.");
        const identity = readIdentity(requestParams, client);
        // A pinned read preserves the owner bytes sealed by retrieval and indexing.
        if (!sourceRef) await syncImportedSourcesIfNeeded(config, appConfig);
        respond(
          true,
          await getMemoryWikiPage({
            config,
            appConfig,
            ...(agentId ? { agentId } : {}),
            lookup,
            fromLine,
            lineCount,
            searchBackend,
            searchCorpus,
            sourceRef,
            readIdentity: identity,
          }),
        );
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.obsidian.status",
    async ({ respond }) => {
      try {
        respond(true, await probeObsidianCli());
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: READ_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.obsidian.search",
    async ({ params: requestParams, respond }) => {
      try {
        const query = readStringParam(requestParams, "query", { required: true });
        respond(true, await runObsidianSearch({ config, query }));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.obsidian.open",
    async ({ params: requestParams, respond }) => {
      try {
        const vaultPath = readStringParam(requestParams, "path", { required: true });
        respond(true, await runObsidianOpen({ config, vaultPath }));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.obsidian.command",
    async ({ params: requestParams, respond }) => {
      try {
        const id = readStringParam(requestParams, "id", { required: true });
        respond(true, await runObsidianCommand({ config, id }));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );

  api.registerGatewayMethod(
    "wiki.obsidian.daily",
    async ({ respond }) => {
      try {
        respond(true, await runObsidianDaily({ config }));
      } catch (error) {
        respondError(respond, error);
      }
    },
    { scope: WRITE_SCOPE },
  );
}

// Memory Wiki plugin module implements source sync behavior.
import type { OpenClawConfig } from "../api.js";
import { syncMemoryWikiBridgeSources, type BridgeMemoryWikiResult } from "./bridge.js";
import {
  refreshMemoryWikiIndexesAfterImport,
  type RefreshMemoryWikiIndexesResult,
} from "./compile.js";
import type { ResolvedMemoryWikiConfig } from "./config.js";
import { syncMemoryWikiUnsafeLocalSources } from "./unsafe-local.js";

export type MemoryWikiImportedSourceSyncResult = BridgeMemoryWikiResult & {
  indexesRefreshed: boolean;
  indexUpdatedFiles: string[];
  indexRefreshReason: RefreshMemoryWikiIndexesResult["reason"];
};

export async function syncMemoryWikiImportedSources(params: {
  config: ResolvedMemoryWikiConfig;
  appConfig?: OpenClawConfig;
}): Promise<MemoryWikiImportedSourceSyncResult> {
  let syncResult: BridgeMemoryWikiResult;
  if (params.config.vaultMode === "bridge") {
    syncResult = await syncMemoryWikiBridgeSources(params);
  } else if (params.config.vaultMode === "unsafe-local") {
    syncResult = await syncMemoryWikiUnsafeLocalSources(params.config);
  } else {
    syncResult = {
      importedCount: 0,
      updatedCount: 0,
      skippedCount: 0,
      removedCount: 0,
      artifactCount: 0,
      workspaces: 0,
      pagePaths: [],
    };
  }
  const refreshResult = await refreshMemoryWikiIndexesAfterImport({
    config: params.config,
    syncResult,
  });
  return {
    ...syncResult,
    indexesRefreshed: refreshResult.refreshed,
    indexUpdatedFiles: refreshResult.compile?.updatedFiles ?? [],
    indexRefreshReason: refreshResult.reason,
  };
}

import path from "node:path";
import {
  createOwnerReadSnapshot,
  deriveReadAdmissionContext,
  digestOwnerReadContent,
  evaluateOwnerReadPolicy,
  evaluateOwnerReadSnapshot,
  matchOwnerReadPin,
  resolveDefaultAgentId,
  resolveSessionAgentId,
  type OwnerReadPolicy,
  type OwnerReadRejectionCode,
  type OwnerReadSnapshotV1,
  type ReadAdmissionContextV1,
  type SourceRefV2,
} from "openclaw/plugin-sdk/memory-host-core";
import { resolveAgentWorkspaceDir } from "openclaw/plugin-sdk/memory-core-host-engine-foundation";
import { getSessionEntry, resolveStorePath } from "openclaw/plugin-sdk/session-store-runtime";
import type { OpenClawConfig } from "../api.js";
import type { ResolvedMemoryWikiConfig } from "./config.js";
import { parseWikiMarkdown, type WikiPageSummary } from "./markdown.js";

export type MemoryWikiReadIdentity = {
  sessionId?: string;
  agentSessionKey?: string;
  workspaceId?: string;
  workspaceDir?: string;
  egressProviderRefs?: string[];
};

function canonicalPath(value: string): string {
  const absolute = path.resolve(value).replace(/\\/g, "/");
  return process.platform === "win32" ? absolute.toLowerCase() : absolute;
}
export function memoryWikiNamespaceId(config: ResolvedMemoryWikiConfig): string {
  return `memory-wiki:${digestOwnerReadContent(canonicalPath(config.vault.path)).slice(7)}`;
}

/** Identity comes from the backend session/workspace owner, never page metadata. */
export function createMemoryWikiReadContext(input: {
  config: ResolvedMemoryWikiConfig;
  appConfig?: OpenClawConfig;
  identity?: MemoryWikiReadIdentity;
}): ReadAdmissionContextV1 {
  const identity = input.identity ?? {};
  const agentId = input.appConfig
    ? identity.agentSessionKey
      ? resolveSessionAgentId({ config: input.appConfig, sessionKey: identity.agentSessionKey })
      : resolveDefaultAgentId(input.appConfig)
    : undefined;
  const workspaceDir =
    identity.workspaceDir ??
    (input.appConfig && agentId
      ? resolveAgentWorkspaceDir(input.appConfig, agentId)
      : input.config.vault.path);
  const rootDigest = digestOwnerReadContent(canonicalPath(workspaceDir));
  const session =
    input.appConfig && agentId && identity.agentSessionKey
      ? getSessionEntry({
          agentId,
          sessionKey: identity.agentSessionKey,
          storePath: resolveStorePath(input.appConfig.session?.store, { agentId }),
        })
      : undefined;
  return deriveReadAdmissionContext({
    principalId: "operator",
    sessionId:
      session?.sessionId ??
      identity.sessionId ??
      identity.agentSessionKey ??
      `knowledge-ui:${agentId ?? "local"}`,
    ...(identity.agentSessionKey ? { sessionKey: identity.agentSessionKey } : {}),
    ...(agentId ? { agentId } : {}),
    workspaceId: identity.workspaceId ?? canonicalPath(workspaceDir),
    workspaceRootDigest: rootDigest,
    ownerNamespaces: [memoryWikiNamespaceId(input.config)],
    policyDigest: digestOwnerReadContent(
      JSON.stringify(["knowledge-owner-read-v1", agentId, rootDigest, input.config.vaultMode]),
    ),
    egressProviderRefs:
      identity.egressProviderRefs ?? Object.keys(input.appConfig?.models?.providers ?? {}),
    expiresAt: new Date(Date.now() + 30_000).toISOString(),
  });
}

function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}
function text(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

export function readMemoryWikiOwnerPolicy(raw: string): OwnerReadPolicy {
  const metadata = parseWikiMarkdown(raw).frontmatter;
  let invalid = false;
  const status = metadata.status === undefined ? "active" : metadata.status;
  if (
    typeof status !== "string" ||
    !["active", "stale", "archived", "revoked", "deleted", "denied"].includes(status)
  )
    invalid = true;
  const trust = metadata.trust === undefined ? "advisory" : metadata.trust;
  if (
    typeof trust !== "string" ||
    !["untrusted", "advisory", "confirmed", "high-trust"].includes(trust)
  )
    invalid = true;
  if (
    metadata.revision !== undefined &&
    !(Number.isSafeInteger(metadata.revision) && Number(metadata.revision) > 0)
  )
    invalid = true;
  const tiers: Record<string, OwnerReadPolicy["sensitivity"]> = {
    public: "public",
    internal: "workspace",
    workspace: "workspace",
    personal: "sensitive",
    private: "sensitive",
    sensitive: "sensitive",
    secret_adjacent: "secret-adjacent",
    "secret-adjacent": "secret-adjacent",
    secret: "secret",
  };
  const tier =
    metadata.sensitivity !== undefined
      ? metadata.sensitivity
      : metadata.privacyTier !== undefined
        ? metadata.privacyTier
        : "workspace";
  const sensitivity =
    typeof tier === "string" && Object.hasOwn(tiers, tier) ? tiers[tier]! : "secret";
  let acl: OwnerReadPolicy["acl"] = { read: ["operator"] };
  if (metadata.acl !== undefined) {
    const ownerAcl = metadata.acl;
    if (
      !record(ownerAcl) ||
      !Array.isArray(ownerAcl.read) ||
      !ownerAcl.read.every((entry) => typeof entry === "string" && Boolean(entry.trim()))
    )
      invalid = true;
    else acl = { read: ownerAcl.read.map((entry: string) => entry.trim()) };
  }
  let scope: OwnerReadPolicy["scope"];
  if (metadata.scope !== undefined && !record(metadata.scope)) invalid = true;
  const ownerScope = record(metadata.scope) ? metadata.scope : {};
  const scopeFields = ["workspaceId", "agentId", "sessionKey", "taskId"] as const;
  for (const key of scopeFields) {
    const value = ownerScope[key] !== undefined ? ownerScope[key] : metadata[key];
    if (value === undefined) continue;
    if (!text(value)) invalid = true;
    else scope = { ...scope, [key]: text(value) };
  }
  if (metadata.retention !== undefined && !record(metadata.retention)) invalid = true;
  const ownerRetention = record(metadata.retention) ? metadata.retention : {};
  const retentionPolicy =
    ownerRetention.policy === undefined ? "source-coupled" : ownerRetention.policy;
  if (
    typeof retentionPolicy !== "string" ||
    !["source-coupled", "promoted", "ephemeral", "legal-hold"].includes(retentionPolicy)
  )
    invalid = true;
  const expiresAt =
    ownerRetention.expiresAt !== undefined ? ownerRetention.expiresAt : metadata.expiresAt;
  if (expiresAt !== undefined && !text(expiresAt)) invalid = true;
  return {
    status: invalid ? "denied" : (status as OwnerReadPolicy["status"]),
    trust: invalid ? "untrusted" : (trust as OwnerReadPolicy["trust"]),
    sensitivity,
    acl,
    ...(scope ? { scope } : {}),
    retention: {
      policy: invalid
        ? "source-coupled"
        : (retentionPolicy as OwnerReadPolicy["retention"]["policy"]),
      ...(text(expiresAt) ? { expiresAt: text(expiresAt) } : {}),
    },
    ...(text(metadata.verifiedAt) ? { verifiedAt: text(metadata.verifiedAt) } : {}),
    ...(text(metadata.updatedAt) ? { updatedAt: text(metadata.updatedAt) } : {}),
  };
}

export function readMemoryWikiOwnerSnapshot(input: {
  page: Pick<WikiPageSummary, "relativePath" | "title" | "revision"> & { raw: string };
  config: ResolvedMemoryWikiConfig;
  context: ReadAdmissionContextV1;
  fromLine?: number;
  lineCount?: number;
  pin?: SourceRefV2;
  signal?: AbortSignal;
}):
  | { status: "admitted"; snapshot: OwnerReadSnapshotV1 }
  | { status: "denied"; reason: OwnerReadRejectionCode } {
  const { page } = input;
  const policy = readMemoryWikiOwnerPolicy(page.raw);
  const admission = evaluateOwnerReadPolicy(
    policy,
    input.context,
    memoryWikiNamespaceId(input.config),
    { signal: input.signal },
  );
  if (admission) return { status: "denied", reason: admission };
  const body = parseWikiMarkdown(page.raw).body;
  const bodyStart = page.raw.length - body.length;
  const lines = body.match(/[^\n]*\n|[^\n]+$/g) ?? [];
  const from = Math.max(0, (input.fromLine ?? 1) - 1);
  const start = bodyStart + lines.slice(0, from).join("").length;
  const end = start + lines.slice(from, from + (input.lineCount ?? 200)).join("").length;
  let startChar = start,
    endChar = end;
  if (input.pin?.locator) {
    const bytes = Buffer.from(page.raw, "utf8");
    const locator = input.pin.locator;
    if (
      locator.startByte < Buffer.byteLength(page.raw.slice(0, bodyStart), "utf8") ||
      locator.endByteExclusive > bytes.length
    )
      return { status: "denied", reason: "invalid_range" };
    let prefix: string, retained: string;
    try {
      const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
      prefix = decoder.decode(bytes.subarray(0, locator.startByte));
      retained = decoder.decode(bytes.subarray(locator.startByte, locator.endByteExclusive));
    } catch {
      return { status: "denied", reason: "invalid_range" };
    }
    startChar = prefix.length;
    endChar = startChar + retained.length;
  }
  const snapshot = createOwnerReadSnapshot({
    raw: page.raw,
    startChar,
    endChar,
    context: input.context,
    policy,
    title: page.title,
    source: {
      domain: "wiki",
      authorityId: "memory-wiki",
      namespaceId: memoryWikiNamespaceId(input.config),
      subjectId: page.relativePath,
      revision:
        page.revision === undefined ? digestOwnerReadContent(page.raw) : String(page.revision),
    },
  });
  snapshot.truncated = startChar > bodyStart || endChar < page.raw.length;
  const reason =
    evaluateOwnerReadSnapshot(snapshot, input.context, { signal: input.signal }) ??
    (input.pin ? matchOwnerReadPin(snapshot, input.pin) : undefined);
  return reason ? { status: "denied", reason } : { status: "admitted", snapshot };
}

// @vitest-environment node
import { mkdtemp, mkdir, readFile, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
